Positive-control probe of plan step 2, at production-at-claim source unchanged; node stdin, exit 0. Full source below so downstream proof survives deletion (no probe file existed). Maps missing test-only .js bridges to existing .ts, no authority mocked. Output: {"goalVersion":1,"designVersion":0,"refused":{"code":"DESIGN_REVISION_CONFLICT","layer":"LEDGER","ok":false,"sourceCode":"EXPECTED_VERSION_CONFLICT","sourceLayer":"DURABLE_STORE"},"control":true}. Proposed plan goal-version offer refuses; identical approved real world with design-version fence accepts.

Run with node --input-type=module and this stdin:
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
registerHooks({ resolve(specifier, context, nextResolve) {
  try { return nextResolve(specifier, context); } catch (error) {
    if (error.code === 'ERR_MODULE_NOT_FOUND' && specifier.endsWith('.js') && specifier.startsWith('.')) {
      const url = new URL(specifier.slice(0, -3) + '.ts', context.parentURL);
      if (existsSync(fileURLToPath(url))) return nextResolve(url.href, context);
    }
    throw error;
  }
}});
const f = await import('./apps/daemon/src/planning/plan-reject-test-fixtures.ts');
const { submitDesignRevision } = await import('./apps/daemon/src/design/design-store.js');
const { designRevisionFixture } = await import('./apps/daemon/src/design/design-test-fixtures.ts');
try {
  const store = f.boundWorld(); const ref = f.committedRevision(store); f.approveGate1(store, ref);
  const goalVersion = store.getAggregateVersion(f.GOAL_ID);
  const designVersion = store.getAggregateVersion(`design:${f.GOAL_ID}`);
  const input = {commandId:'probe-goal-version', contractRef:ref, correlationId:'probe', decidedAt:'2026-09-06T00:00:00.000Z', expectedVersion:goalVersion, goalRef:f.GOAL_ID, principalId:f.OPERATOR, projectId:f.PROJECT_ID, revision:designRevisionFixture()};
  const refused = submitDesignRevision(store,input);
  const accepted = submitDesignRevision(store,{...input,commandId:'probe-design-version',expectedVersion:designVersion});
  console.log(JSON.stringify({goalVersion,designVersion,refused,control:accepted.ok}));
} finally { f.closeStores(); }
